package io.github.jesterportfolio.hearth.features;

import io.github.jesterportfolio.hearth.combat.*;
import io.github.jesterportfolio.hearth.persistence.*;
import java.io.*;
import java.util.*;
import java.util.concurrent.*;
import java.util.function.Function;

/** 마지막 확정 전투/복귀 경계. 활성/이동 불명은 재소환·재지급하지 않고 HOLD 판정합니다. */
public final class RecoveryLedger {
    public enum Phase{ACTIVE,RETURN_PENDING,RETURNING,DONE}public enum Action{NONE,RETURN,HOLD}
    public record State(UUID attempt,Phase phase,UUID world,CombatContent.Exit exit,String mode,UUID claim){public State{Objects.requireNonNull(attempt);Objects.requireNonNull(phase);Objects.requireNonNull(world);Objects.requireNonNull(exit);if(!Set.of("SURVIVAL","ADVENTURE").contains(mode)||(phase==Phase.RETURNING||phase==Phase.DONE)!=(claim!=null))throw new IllegalArgumentException("RECOVERY_STATE");}}
    private final FeatureStore store;public RecoveryLedger(FeatureStore store){this.store=store;}
    public static Action restart(State s){return switch(s.phase){case ACTIVE,RETURNING->Action.HOLD;case RETURN_PENDING->Action.RETURN;case DONE->Action.NONE;};}
    public static State start(State old,UUID attempt,UUID parent,UUID world,CombatContent.Exit exit,String mode){if(old!=null){if(old.phase==Phase.ACTIVE&&old.attempt.equals(attempt))return old;if(old.phase!=Phase.DONE&&!(old.phase==Phase.ACTIVE&&old.attempt.equals(parent)))throw new IllegalStateException("RECOVERY_PENDING_OR_HOLD");if(old.phase==Phase.DONE&&old.attempt.equals(attempt))throw new IllegalStateException("RECOVERY_REPLAY");}return new State(attempt,Phase.ACTIVE,world,exit,mode,null);}
    public static State end(State old,UUID attempt){if(old==null||!old.attempt.equals(attempt))throw new IllegalStateException("RECOVERY_ATTEMPT");return old.phase==Phase.ACTIVE?new State(old.attempt,Phase.RETURN_PENDING,old.world,old.exit,old.mode,null):old;}
    public static State claim(State old,UUID attempt,UUID request){if(old==null||!old.attempt.equals(attempt)||old.phase!=Phase.RETURN_PENDING&&!(old.phase==Phase.RETURNING&&request.equals(old.claim)))throw new IllegalStateException("RECOVERY_CLAIM");return new State(old.attempt,Phase.RETURNING,old.world,old.exit,old.mode,request);}
    public static State done(State old,UUID attempt,UUID request){if(old==null||!old.attempt.equals(attempt)||!request.equals(old.claim)||old.phase!=Phase.RETURNING&&old.phase!=Phase.DONE)throw new IllegalStateException("RECOVERY_COMMIT");return new State(old.attempt,Phase.DONE,old.world,old.exit,old.mode,request);}
    public CompletionStage<Optional<State>> read(ServerProgressAccess.Context c){return store.read(c,"combat_return","current").thenApply(row->row.map(r->decode(r.payload())));}
    private CompletionStage<State> change(ServerProgressAccess.Context c,Function<State,State> operation){return store.read(c,"combat_return","current").thenCompose(row->{State old=row.map(r->decode(r.payload())).orElse(null),next=operation.apply(old);if(next.equals(old))return CompletableFuture.completedFuture(next);return store.write(c,"combat_return","current",row.map(FeatureStore.Saved::revision).orElse(-1L),encode(next)).thenApply(saved->next);});}
    public CompletionStage<State> start(ServerProgressAccess.Context c,UUID attempt,UUID parent,UUID world,CombatContent.Exit exit,String mode){return change(c,old->start(old,attempt,parent,world,exit,mode));}
    public CompletionStage<State> end(ServerProgressAccess.Context c,UUID attempt){return change(c,old->end(old,attempt));}public CompletionStage<State> claim(ServerProgressAccess.Context c,UUID attempt,UUID request){return change(c,old->claim(old,attempt,request));}public CompletionStage<State> done(ServerProgressAccess.Context c,UUID attempt,UUID request){return change(c,old->done(old,attempt,request));}
    private static void uuid(DataOutputStream out,UUID id)throws IOException{out.writeLong(id.getMostSignificantBits());out.writeLong(id.getLeastSignificantBits());}private static UUID uuid(DataInputStream in)throws IOException{return new UUID(in.readLong(),in.readLong());}
    public static byte[] encode(State s){try{var bytes=new ByteArrayOutputStream();var out=new DataOutputStream(bytes);out.writeInt(1);uuid(out,s.attempt);out.writeUTF(s.phase.name());uuid(out,s.world);out.writeDouble(s.exit.entry().x());out.writeDouble(s.exit.entry().y());out.writeDouble(s.exit.entry().z());out.writeFloat(s.exit.yaw());out.writeFloat(s.exit.pitch());out.writeDouble(s.exit.healthFraction());out.writeInt(s.exit.effects().size());for(var effect:s.exit.effects()){out.writeUTF(effect.type());out.writeInt(effect.amplifier());out.writeInt(effect.ticks());}out.writeUTF(s.mode);out.writeBoolean(s.claim!=null);if(s.claim!=null)uuid(out,s.claim);return bytes.toByteArray();}catch(IOException e){throw new IllegalStateException(e);}}
    public static State decode(byte[] bytes){try{var in=new DataInputStream(new ByteArrayInputStream(bytes));if(in.readInt()!=1)throw new IOException();var attempt=uuid(in);var phase=Phase.valueOf(in.readUTF());var world=uuid(in);var point=new FieldContent.Point(in.readDouble(),in.readDouble(),in.readDouble());float yaw=in.readFloat(),pitch=in.readFloat();double health=in.readDouble();int size=in.readInt();if(size<0||size>4)throw new IOException();var effects=new ArrayList<CombatContent.Effect>();for(int i=0;i<size;i++)effects.add(new CombatContent.Effect(in.readUTF(),in.readInt(),in.readInt()));var mode=in.readUTF();var claim=in.readBoolean()?uuid(in):null;var state=new State(attempt,phase,world,new CombatContent.Exit(point,yaw,pitch,health,effects),mode,claim);if(in.available()!=0)throw new IOException();return state;}catch(IOException|RuntimeException e){throw new IllegalArgumentException("INVALID_RECOVERY_STATE");}}
}
